2	
3	const SURVIVAL_NEIGHBOR_COUNTS = [2, 3];
4	const BIRTH_NEIGHBOR_COUNT = 3;
5	
6	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
7	
8	const neighborsOf = ([x, y]: Cell): Cell[] =>
9	  [-1, 0, 1].flatMap((dx) =>
10	    [-1, 0, 1]
11	      .filter((dy) => !(dx === 0 && dy === 0))
12	      .map((dy): Cell => [x + dx, y + dy]),
13	  );
14	
15	const uniqueCells = (cells: Cell[]): Cell[] => [
16	  ...new Map(cells.map((cell): [string, Cell] => [keyOf(cell), cell])).values(),
17	];
18	
19	const countNeighborsPerCell = (liveCells: Cell[]): Map<string, number> =>
20	  liveCells.flatMap(neighborsOf).reduce((counts, neighbor) => {
21	    const key = keyOf(neighbor);
22	    return counts.set(key, (counts.get(key) ?? 0) + 1);
23	  }, new Map<string, number>());
24	
25	export function nextGeneration(liveCells: Cell[]): Cell[] {
26	  const neighborCounts = countNeighborsPerCell(liveCells);
27	  const liveKeys = new Set(liveCells.map(keyOf));
28	  const neighborCountOf = (cell: Cell): number =>
29	    neighborCounts.get(keyOf(cell)) ?? 0;
30	
31	  const survivors = liveCells.filter((cell) =>
32	    SURVIVAL_NEIGHBOR_COUNTS.includes(neighborCountOf(cell)),
33	  );
34	
35	  const births = uniqueCells(
36	    liveCells
37	      .flatMap(neighborsOf)
38	      .filter((cell) => !liveKeys.has(keyOf(cell)))
39	      .filter((cell) => neighborCountOf(cell) === BIRTH_NEIGHBOR_COUNT),
40	  );
41	
42	  return [...survivors, ...births];
43	}
