1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	// The spec describes generations as sets of coordinates, so comparisons of a
5	// whole grid ignore the order cells come back in.
6	const sorted = (cells: Cell[]): Cell[] =>
7	  [...cells].sort(([ax, ay], [bx, by]) => ax - bx || ay - by);
8	
9	describe("Game of Life - nextGeneration", () => {
10	  it("returns an empty grid for an empty grid — [] → []", () => {
11	    expect(nextGeneration([])).toEqual([]);
12	  });
13	  it("Single cell dies: [(0,0)] → []", () => {
14	    expect(nextGeneration([[0, 0]])).toEqual([]);
15	  });
16	  it("Rule 1 underpopulation: a live cell with 1 neighbor dies — [(0,1), (1,1)] → []", () => {
17	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
18	  });
19	  it("Rule 2 survival: a live cell with 2 neighbors lives on", () => {
20	    // Horizontal triple: (1,0) has exactly 2 live neighbors and survives.
21	    expect(nextGeneration([[0, 0], [1, 0], [2, 0]])).toContainEqual([1, 0]);
22	  });
23	  it("Rule 2 survival: a live cell with 3 neighbors lives on", () => {
24	    // In a 2x2 block each cell has exactly 3 live neighbors and survives.
25	    expect(nextGeneration([[0, 0], [1, 0], [0, 1], [1, 1]])).toContainEqual([0, 0]);
26	  });
27	  it("Rule 3 overpopulation: a live cell with more than 3 neighbors dies", () => {
28	    // '###/.#./###' — the center (1,1) has 6 live neighbors and dies.
29	    const grid: Cell[] = [
30	      [0, 0], [1, 0], [2, 0],
31	      [1, 1],
32	      [0, 2], [1, 2], [2, 2],
33	    ];
34	    expect(nextGeneration(grid)).not.toContainEqual([1, 1]);
35	  });
36	  it("Rule 4 reproduction: a dead cell with exactly 3 neighbors becomes alive — [(0,0), (1,0), (0,1)] → (1,1) alive", () => {
37	    expect(nextGeneration([[0, 0], [1, 0], [0, 1]])).toContainEqual([1, 1]);
38	  });
39	  it("Rule 4 example in full: '##./#../...' → '##./##./...'", () => {
40	    const gen0: Cell[] = [[0, 0], [1, 0], [0, 1]];
41	    const gen1: Cell[] = [[0, 0], [1, 0], [0, 1], [1, 1]];
42	    expect(sorted(nextGeneration(gen0))).toEqual(sorted(gen1));
43	  });
44	  it("Rule 3 example in full: '###/.#./###' → '#.#/#.#/#.#' within the 3x3 window", () => {
45	    const gen0: Cell[] = [
46	      [0, 0], [1, 0], [2, 0],
47	      [1, 1],
48	      [0, 2], [1, 2], [2, 2],
49	    ];
50	    // The spec's ASCII art crops to the original 3x3 window. On an infinite
51	    // grid two further cells are born just outside it, at (1,-1) and (1,3).
52	    const gen1: Cell[] = [
53	      [0, 0], [2, 0],
54	      [0, 2], [2, 2],
55	      [1, 0], [1, 2],
56	      [1, -1], [1, 3],
57	    ];
58	    expect(sorted(nextGeneration(gen0))).toEqual(sorted(gen1));
59	  });
60	  it("Block still life stays unchanged — [(0,0), (1,0), (0,1), (1,1)] → same 4 cells", () => {
61	    const block: Cell[] = [[0, 0], [1, 0], [0, 1], [1, 1]];
62	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
63	  });
64	  it("Blinker gen 0 → gen 1 — [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]", () => {
65	    const vertical: Cell[] = [[0, 0], [0, 1], [0, 2]];
66	    const horizontal: Cell[] = [[-1, 1], [0, 1], [1, 1]];
67	    expect(sorted(nextGeneration(vertical))).toEqual(sorted(horizontal));
68	  });
69	  it("Blinker gen 1 → gen 2 — [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]", () => {
70	    const horizontal: Cell[] = [[-1, 1], [0, 1], [1, 1]];
71	    const vertical: Cell[] = [[0, 0], [0, 1], [0, 2]];
72	    expect(sorted(nextGeneration(horizontal))).toEqual(sorted(vertical));
73	  });
74	  it("handles negative coordinates — a block at (-3,-3) stays unchanged", () => {
75	    const block: Cell[] = [[-3, -3], [-2, -3], [-3, -2], [-2, -2]];
76	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
77	  });
78	});
